let timer:ReturnType<typeof setInterval>|undefined;const clock=new TrainingClock();let running=false;let feedback:{answer:TrainingAnswer;q:Question}|null=null;let revealed=false;let hint=false;let transcript=false;let audioFallback=false;let audioHeard=false;let playing=false;let initialPlayback=false;let voicePlayToken=0;let toastTimer:ReturnType<typeof setTimeout>;
