 listen:{en:'Listen & Select',uk:'Слухай і вибирай',description:'Hear a callout. Choose its meaning.',ukDescription:'Прослухайте колаут і виберіть переклад.',icon:'headphones'},
 'listen-locate':{en:'Listen & Locate',uk:'Слухай і знаходь',description:'No written prompt. Just you and the map.',ukDescription:'Визначте позицію на карті за голосом.',icon:'map'},
 multi:{en:'Multi-Callout',uk:'Ланцюжок колаутів',description:'Remember three calls in the right order.',ukDescription:'Відтворіть три колаути в правильному порядку.',icon:'headphones'},
