function toast(message:string,error=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.setAttribute('role',error?'alert':'status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),6500);}
function stop(){clearInterval(timer);timer=undefined;voicePlayToken++;voice.cancel();playing=false;initialPlayback=false;running=false;}
async function commit(next:AppData){if(saving)throw new Error(t('Please wait for the previous save.','Дочекайтеся збереження.'));saving=true;root.setAttribute('aria-busy','true');try{await repository.save(next);data=next;dict=new PositionDictionaryService(data.dictionary??dictionary);engine=new LearningEngine(dict);}finally{saving=false;root.removeAttribute('aria-busy');}}
function stat(label:string,value:string,foot:string,ico:string){return `<div class="panel stat"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function button(label:string,action:string,primary=false){return `<button class="${primary?'primary':''}" data-action="${action}">${label}</button>`;}
function link(label:string,path:string,primary=false){return `<a class="button ${primary?'primary':''}" href="#${path}">${label}</a>`;}
function heading(kicker:string,title:string,description:string,extra=''){return `<div class="page-title"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function empty(title:string,description:string,ico='chart'){return `<div class="empty">${icon(ico)}<h3>${title}</h3><p>${description}</p></div>`;}
function date(value:number){return new Date(value).toLocaleDateString(data.settings.native==='uk'?'uk-UA':'en-GB',{day:'numeric',month:'short'});}
function time(ms:number){return ms?(ms/1000).toFixed(1)+'s':'—';}
function options(values:[string,string][],value:string|number){return values.map(([id,label])=>`<option value="${e(id)}" ${String(value)===id?'selected':''}>${label}</option>`).join('');}
function titleForRoute(){const path=route();return path.startsWith('/session')?t('Training session','Тренування'):path.startsWith('/results')?t('Session report','Результати'):({'/':t('Dashboard','Головна'),'/maps':t('Interactive Maps','Карти'),'/learn':t('Learn Positions','Вивчення позицій'),'/practice':t('Practice','Практика'),'/listening':t('Listening Training','Аудіювання'),'/voice':t('Voice Simulator','Голос команди'),'/round':t('Round Simulation','Симуляція раунду'),'/stats':t('Statistics','Статистика'),'/settings':t('Settings','Налаштування')}[path]??'Callout');}
function shell(content:string){const path=route();const navs=[['/',t('Dashboard','Головна'),'grid'],['/maps',t('Interactive Maps','Карти'),'map'],['/learn',t('Learn Positions','Позиції'),'book'],['/practice',t('Practice','Практика'),'target'],['/listening',t('Listening Training','Аудіювання'),'headphones'],['/voice',t('Voice Simulator','Голос команди'),'mic'],['/round',t('Round Simulation','Раунди'),'round'],['/stats',t('Statistics','Статистика'),'chart']];return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/"><img src="${import.meta.env.BASE_URL}assets/callout.svg" alt=""><span>callout</span><sup>LAB</sup></a><nav aria-label="${t('Main navigation','Головна навігація')}"><div class="eyebrow nav-label">${t('YOUR TRAINING SPACE','ТРЕНУВАЛЬНА БАЗА')}</div>${navs.map(([href,label,ico])=>`<a class="nav-link ${path===href?'active':''}" href="#${href}" ${path===href?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-link ${path==='/settings'?'active':''}" href="#/settings">${icon('settings')}<span>${t('Settings','Налаштування')}</span></a><div class="local-badge"><i></i><div>${t('LOCAL FIRST. ALWAYS.','ДАНІ НА ПРИСТРОЇ.')}<br>${t('No account. No tracking.','Без реєстрації та трекерів.')}</div></div></div></aside><div class="main-column"><header class="page-header"><div class="breadcrumb">${icon('grid')}<span>Workspace</span><span>/</span><strong>${titleForRoute()}</strong></div><div class="row"><span class="status-pill"><i></i>${navigator.onLine?t('Local training','Локальне навчання'):t('Offline mode','Офлайн-режим')}</span><a class="profile" href="#/settings" aria-label="${t('Profile and settings','Профіль і налаштування')}"><div class="avatar">${e(data.settings.name.slice(0,2).toUpperCase())}</div><div>${e(data.settings.name)}<small>${languageLabel(data.settings.native)} → ${languageLabel(data.settings.target)} · ${levelName(LanguageImmersionEngine.level(data,ids()))}</small></div>${icon('settings')}</a></div></header><main class="content" id="main">${content}<footer class="app-footer"><span>CALLOUT / ${t('Understand the call. Make the play.','Розумій команду. Дій швидше.')}</span><span>${t('Independent training tool · Not affiliated with Valve','Незалежний тренажер · Не пов’язаний із Valve')}</span></footer></main></div></div>`;}
function onboarding(){return `<div class="onboarding"><section class="onboard-story"><div class="brand"><img src="${import.meta.env.BASE_URL}assets/callout.svg" alt=""><span>callout</span><sup>LAB</sup></div><span class="eyebrow">CS2 / COMMUNICATION TRAINING</span><h1>Understand the call.<br><em>Make the play.</em></h1><p>Bridge the gap between English and Ukrainian callouts. Learn the position, hear the message, react with confidence.</p><div class="row wrap"><span class="status-pill">20 verified Mirage positions</span><span class="status-pill">Local & private</span></div><p class="tiny">An independent training space. No game integration. No account required.<br>Самостійний тренажер. Без реєстрації та інтеграції з грою.</p></section><section class="onboard-form"><div><span class="eyebrow">01 / YOUR STARTING POINT</span><h2>Let's find your language.</h2><p>Налаштуйте навчання. Усе можна змінити пізніше.</p><form id="onboarding-form" class="form-grid"><label class="field">Player name / Ім’я<input name="name" maxlength="60" required value="${e(data.settings.name)}" autocomplete="nickname"></label><div class="field-row"><label class="field">Native language / Основна мова<select name="native">${options([['uk','Українська'],['en','English']],data.settings.native)}</select></label><label class="field">Learning language / Мова навчання<select name="target">${options([['en','English'],['uk','Українська']],data.settings.target)}</select></label></div><label class="field">Starting level / Рівень<select name="initial">${options([['beginner','Beginner · Початковий'],['intermediate','Intermediate · Середній'],['advanced','Advanced · Просунутий']],data.settings.initial)}</select></label><label class="field">First map / Перша карта<select name="mapId"><option value="mirage">Mirage · Recommended / Рекомендуємо</option></select></label><label class="checkbox"><input type="checkbox" name="placement">Optional placement test / Вступний тест</label><p class="notice">Your progress stays on this device. Microphone access is never requested.<br>Прогрес зберігається на пристрої. Доступ до мікрофона не потрібен.</p><button type="submit" class="primary">Enter your training space ${icon('arrow')}</button></form></div></section></div>`;}
function dashboard(){const s=StatisticsService.calculate(data,ids()),level=LanguageImmersionEngine.level(data,ids());const readiness=CommunicationReadinessCalculator.calculate(data,ids());const active=currentSession();const last=data.sessions.filter(s=>s.status==='complete').at(-1);return heading(t('YOUR NEXT ROUND STARTS HERE','НОВИЙ РАУНД ПОЧИНАЄТЬСЯ ТУТ'),`${t('Good to see you','З поверненням')}, ${e(data.settings.name)}<span class="accent">.</span>`,t('A little practice. A clearer call. A better teammate.','Трохи практики. Зрозуміліші колаути. Упевненіша комунікація.'),`<div class="row">${link(icon('chart')+' '+t('Statistics','Статистика'),'/stats')}<span class="status-pill">${languageLabel(data.settings.native)} ${icon('arrow')} ${languageLabel(data.settings.target)}</span></div>`)+`<section class="stats-grid" aria-label="Training statistics">${stat(t('Communication readiness','Готовність до комунікації'),readiness+'<small>%</small>',t('A learning metric, not a match guarantee','Навчальна оцінка, не гарантія перемоги'),'round')}${stat(t('Positions mastered','Засвоєно позицій'),`${s.learned}<small> / ${s.total}</small>`,t('Built through spaced repetition','Стійке інтервальне повторення'),'book')}${stat(t('Answer accuracy','Точність відповідей'),s.answers?Math.round(s.accuracy*100)+'<small>%</small>':'—',`${s.answers} ${t('unaided scored answers','відповідей без підказок')}`,'target')}${stat(t('Average reaction','Середня реакція'),s.averageMs?time(s.averageMs):'—',t('From real training answers','За результатами тренувань'),'clock')}</section><div class="dashboard-grid"><section class="panel map-feature"><div class="panel-header"><div class="row"><div class="map-badge"><span>M</span><div>Mirage<small style="display:block;font-weight:400;color:var(--muted);font-size:10px">${t('YOUR ACTIVE MAP','ПОТОЧНА КАРТА')}</small></div></div></div><span class="tag">${t('Verified pack','Перевірений набір')}</span></div><div class="map-host" id="dashboard-map"></div><div class="map-feature-footer"><div><h3>${t('Know the position. Own the call.','Знай позицію. Розумій колаут.')}</h3><small>${s.total} ${t('positions · EN / UA · Mirage radar','позицій · EN / UA · Радар Mirage')}</small></div>${link(t('Explore map','Відкрити карту')+' '+icon('arrow'),'/maps',true)}</div></section><div class="stack"><section class="panel hero-next"><div class="icon-wrap">${icon('play')}</div><span class="eyebrow">${active?t('PICK UP WHERE YOU LEFT OFF','ПРОДОВЖУЙТЕ НАВЧАННЯ'):t('YOUR NEXT STEP','НАСТУПНИЙ КРОК')}</span><h2>${active?modeName(active.mode):s.due?t('Time for a refresh','Час повторити'):t('Build your callout instinct','Розвивайте ігровий слух')}</h2><p>${active?`${active.index} / ${active.questions.length} ${t('questions completed. Your place is saved.','запитань пройдено. Прогрес збережено.')}`:t('Start with familiar names. Move to faster, more natural communication.','Почніть зі знайомих назв і переходьте до швидкої комунікації.')}</p>${active?link(t('Continue session','Продовжити заняття')+' '+icon('arrow'),'/session',true):`<button class="button primary" data-start="${s.due?'mistakes':'choice'}">${t('Start training','Почати тренування')} ${icon('arrow')}</button>`}</section><section class="panel"><div class="row spread"><span class="eyebrow">${t('LANGUAGE IMMERSION','МОВНЕ ЗАНУРЕННЯ')}</span><span class="accent" style="font-size:13px">${LanguageImmersionEngine.ratios[level]*100}% ${languageLabel(data.settings.target)}</span></div><div class="immersion-levels">${[0,1,2,3].map(l=>`<span class="${l<=level?'on':''}"></span>`).join('')}</div><div class="row spread"><h3>${levelName(level)}</h3><a class="subtle-button" href="#/settings">${t('Adjust','Змінити')} ↗</a></div><p style="font-size:11px;margin-top:8px">${t('Tasks mix languages using your current level. Accuracy, speed and retention guide progression.','Мова завдань залежить від рівня. Точність, швидкість і стійкість знань керують переходом.')}</p></section></div></div><div class="section-heading"><h2>${t('Find your training rhythm','Виберіть своє тренування')}</h2><span>${t('One shared progress system','Єдина система прогресу')}</span></div><section class="training-grid">${(['flashcards','speed','listen','round'] as Mode[]).map(mode=>modeCard(mode,true)).join('')}</section><div class="section-heading"><h2>${t('Recent sessions','Останні заняття')}</h2>${link(t('All statistics','Уся статистика')+' ↗','/stats')}</div><section class="panel">${history(4)}${!last?`<p class="map-note">${t('Your first results will appear after training. No sample statistics.','Результати з’являться після тренування. Статистика ще порожня.')}</p>`:''}</section>`;}
function modeCard(mode:Mode,compact=false){const m=modeInfo[mode];return `<${compact?'button':'article'} class="training-card" ${compact?`data-start="${mode}"`:''}><span class="icon-wrap">${icon(m.icon)}</span><h3>${modeName(mode)}</h3><p>${t(m.description,m.ukDescription)}</p>${compact?'':`<button data-start="${mode}" class="button">${t('Start session','Почати')} ${icon('arrow')}</button>`}</${compact?'button':'article'}>`;}
function history(limit=20){const list=[...data.sessions].reverse().slice(0,limit);if(!list.length)return empty(t('A fresh start','Чистий аркуш'),t('Finish a session to see your progress here.','Пройдіть тренування, щоб побачити результати.'));return `<ul class="history-list">${list.map(s=>`<li><div class="row">${icon(modeInfo[s.mode].icon)}<div>${modeName(s.mode)}<small>Mirage · ${date(s.startedAt)} · ${s.status==='active'?t('In progress','Триває'):`${s.answers.length} ${t('answers','відповідей')}`}</small></div></div><div class="row"><span class="${s.answers.length?'accent':'muted'}">${s.answers.length?Math.round(s.answers.filter(a=>a.correct).length/s.answers.length*100)+'%':'—'}</span>${s.status==='complete'?link(t('Report','Звіт'),'/results/'+s.id):s.id===data.activeSessionId?link(t('Resume','Продовжити'),'/session'):`<button data-resume-session="${s.id}">${t('Resume','Продовжити')}</button>`}</div></li>`).join('')}</ul>`;}
function mapsPage(learning=false){return heading(t('MAP KNOWLEDGE / MIRAGE','ЗНАННЯ КАРТИ / MIRAGE'),learning?t('Make every position familiar.','Вивчіть кожну позицію.'):t('One map. Two languages.','Одна карта. Дві мови.'),t('Explore the original schematic, search aliases and build your review list.','Досліджуйте карту, шукайте альтернативні назви та зберігайте позиції для повторення.'),learning?`<button class="button primary" data-start="flashcards">${t('Start flashcards','Учити за картками')} ${icon('arrow')}</button>`:'')+`<div class="map-layout"><section class="panel"><div class="toolbar"><input id="position-search" type="search" value="${e(search)}" placeholder="${t('Search names or aliases…','Пошук назв та альтернатив…')}" aria-label="${t('Search positions','Пошук позицій')}"><select id="zone" aria-label="${t('Filter by zone','Фільтр зони')}">${options([['all',t('All zones','Усі зони')],['A','A site'],['B','B site'],['Mid','Mid']],zone)}</select><select id="map-language" aria-label="${t('Marker language','Мова маркерів')}">${options([['both','EN + UA'],['en','English'],['uk','Українська']],mapLanguage)}</select><label class="checkbox"><input id="hide-labels" type="checkbox" ${mapHidden?'checked':''}>${t('Hide names','Приховати назви')}</label></div><div class="row spread" style="margin-bottom:12px"><span class="tag">${t('Main level','Основний рівень')}</span><span class="muted" id="map-count" style="font-size:11px"></span></div><div id="explorer-map" class="map-host"></div><p class="map-note">${t('Mirage radar from your supplied reference. Markers indicate positions; Underpass is below the main level.','Радар Mirage з наданого вами зображення. Маркери позначають позиції; підземний прохід проходить нижче основного рівня.')}</p></section><aside class="panel position-card" id="position-card"></aside></div><div class="section-heading"><h2>${t('Map library','Бібліотека карт')}</h2><span>${t('Quality before quantity','Якість важливіша за кількість')}</span></div><div class="map-selection">${dict.data.maps.map(m=>`<article class="map-choice ${m.available?'':'unavailable'}"><span class="tag ${m.available?'':'orange'}">${m.available?t('Ready to train','Доступна'):t('Planned · No learning data','У планах · Немає навчальних даних')}</span><h3>${e(m.name)}</h3><p>${m.available?`${dict.positions(m.id).length} ${t('verified positions','перевірених позицій')}`:t('Available after source and map review.','Буде доступна після перевірки даних і карти.')}${m.layers.length>1?' · Upper / Lower':''}</p>${m.available?`<button class="button" data-action="select-mirage">${t('Selected','Вибрано')} ${icon('check')}</button>`:''}</article>`).join('')}</div>`;}
function positionCard(){const p=dict.get(selected),progress=data.progress[p.id];return `<div><div class="position-number">MIRAGE / ${p.zone.toUpperCase()} / ${p.id.split('.')[1].toUpperCase()}</div><span class="eyebrow">ENGLISH</span><h2>${e(dict.name(p.id,'en'))}</h2><div class="translation">${e(dict.name(p.id,'uk'))}</div><span class="tag ${SpacedRepetitionEngine.mastered(progress)?'':'orange'}">${SpacedRepetitionEngine.mastered(progress)?t('Mastered','Засвоєно'):progress?t('Learning','Вивчається'):t('New position','Нова позиція')}</span><div class="row"><button data-action="speak-position" aria-label="${t('Listen to position','Прослухати позицію')}">${icon('volume')} ${languageLabel(data.settings.target)}</button><button data-action="save-review">${icon('repeat')} ${data.review.includes(p.id)?t('Saved','Збережено'):t('Review','Повторити')}</button></div><span class="eyebrow">${t('ALTERNATIVE NAMES','АЛЬТЕРНАТИВНІ НАЗВИ')}</span><p style="font-size:12px;margin-top:8px">${(['en','uk'] as const).map(lang=>`${languageLabel(lang)}: ${dict.aliases(p.id,lang).map(a=>e(a.name)).join(', ')||'—'}`).join('<br>')}</p><div class="source-list">${t('Community-verified vocabulary. Regional usage varies.','Перевірені англійські колаути з українським перекладом. Українські назви є поясненнями, а не твердженням про єдиний стандарт спільноти.')}${dict.data.sources.filter(s=>[...p.sourceIds,...dict.data.translations.filter(tr=>tr.positionId===p.id).map(tr=>tr.sourceId),...dict.data.aliases.filter(a=>a.positionId===p.id).map(a=>a.sourceId)].includes(s.id)).map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`).join('')}</div></div><div><div class="panel-header"><span class="eyebrow">${t('POSITION INDEX','СПИСОК ПОЗИЦІЙ')}</span><span style="font-size:10px;color:var(--muted)">${progress?`${progress.correct} ✓ / ${progress.errors} ×`:'0 ✓ / 0 ×'}</span></div><div class="position-list">${dict.search(search,zone).map(p=>`<button data-select="${e(p.id)}" class="${selected===p.id?'active':''}">${e(dict.name(p.id,data.settings.target))}<small>${p.zone}</small></button>`).join('')||`<p>${t('No matches. Try another name.','Немає збігів. Спробуйте іншу назву.')}</p>`}</div></div>`;}
function practice(){return heading(t('PRACTICE / MIRAGE','ПРАКТИКА / MIRAGE'),t('Recognition becomes instinct.','Розпізнавання стане звичкою.'),t('Every answer updates your progress. Due and unfamiliar positions get priority.','Кожна відповідь оновлює прогрес. Спочатку — забуті та нові позиції.'))+`<div class="notice" style="margin-bottom:22px">${t('Seven learning stages: discover → recognize → reverse → locate → react → context → immersion. Start anywhere; revisit weak positions.','Сім етапів: знайомство → розпізнавання → зворотний переклад → карта → швидкість → контекст → занурення. Почніть із потрібного етапу та повертайтеся до складних позицій.')}</div><div class="mode-grid">${(['flashcards','choice','reverse','locate','speed','mistakes'] as Mode[]).map(m=>modeCard(m)).join('')}</div>`;}
function listening(voicePage=false){return heading(t('LISTEN / UNDERSTAND / REACT','СЛУХАЙ / РОЗУМІЙ / РЕАГУЙ'),voicePage?t('Your team is calling.','Союзники передають інформацію.'):t('Train your ears for the round.','Готуйте слух до нового раунду.'),t('Ryan recordings for English; local system voice fallback for Ukrainian. Adjust playback in Settings.','Записи Ryan англійською; для української — локальний системний голос. Параметри відтворення — у налаштуваннях.'),link(icon('settings')+' '+t('Audio settings','Налаштування звуку'),'/settings'))+`<div class="notice ${voice.available(data.settings.target,data.settings)?'':'warning'}" style="margin-bottom:22px">${voice.available(data.settings.target,data.settings)?t('A recording or system voice is available. The playback source is shown during training.','Доступний записаний або системний голос. Джерело показується під час відтворення.'):t('No audio source is available or playback is disabled. Check voice settings. Text fallback does not count as listening accuracy.','Озвучування недоступне або вимкнене. Перевірте налаштування голосу. Текстовий режим не зараховується до аудіостатистики.')}</div><div class="mode-grid">${(voicePage?['voice','speak']:['listen','listen-locate','multi','speak'] as Mode[]).map(m=>modeCard(m as Mode)).join('')}</div>`;}
function roundPage(){return heading(t('ROUND SIMULATOR / MIRAGE','СИМУЛЯТОР РАУНДУ / MIRAGE'),t('Read the round through the calls.','Стежте за раундом за колаутами.'),t('Coherent, authored training scenarios. No game connection or simulated AI.','Авторські навчальні сценарії. Без підключення до гри та імітації штучного інтелекту.'))+`<div class="settings-grid"><section class="panel stack"><div><span class="eyebrow">${t('ROUND RULES','ПРАВИЛА РАУНДУ')}</span><h2 style="margin-top:10px">${t('Choose the pressure','Виберіть навантаження')}</h2></div><label class="field">${t('Round mode','Режим')}<select id="round-mode">${options([['training',t('Training · No timer, full hints','Навчальний · Без таймера, з підказками')],['normal',t('Normal · 9 seconds per call','Звичайний · 9 секунд на колаут')],['competitive',t('Competitive · 4.5 seconds, minimal hints','Змагальний · 4,5 секунди')],['reverse',t('Reverse Communication · Type the call','Зворотна комунікація · Введіть назву')]],data.settings.roundMode)}</select></label><p>${t('A round follows one situation from first contact to the last enemy. Each decision is checked and saved immediately.','Раунд проводить через ситуацію від першого контакту до останнього противника. Кожна відповідь перевіряється та зберігається.')}</p><p class="notice">${t('Learning metric only. This is not a prediction of match performance.','Навчальне тренування. Не прогнозує результат реального матчу.')}</p></section><section class="stack">${scenarios.map((s,i)=>`<article class="panel"><div class="row spread"><span class="tag">${s.side} / MIRAGE</span><span class="muted" style="font-size:11px">${s.events.length} ${t('events','події')}</span></div><h2 style="margin:18px 0 8px">${e(s.name)}</h2><p>${i===0?t('Defend A through an incoming split, the plant area and a final rotation.','Захищайте A: вихід із двох напрямків, зона встановлення та остання ротація.'):t('Secure the middle, identify defenders and follow the rotation toward B.','Контролюйте центр, визначайте захисників і стежте за ротацією до B.')}</p><button data-scenario="${i}" class="primary" style="margin-top:20px">${t('Start round','Почати раунд')} ${icon('arrow')}</button></article>`).join('')}</section></div>`;}
function statistics(){const s=StatisticsService.calculate(data,ids());const recent=data.sessions.filter(s=>s.status==='complete').slice(-12);const hard=dict.positions().filter(p=>data.progress[p.id]?.errors).sort((a,b)=>(data.progress[b.id]?.errors??0)-(data.progress[a.id]?.errors??0)).slice(0,6);const audio=s.audio;return heading(t('PROGRESS / REAL RESULTS','ПРОГРЕС / РЕАЛЬНІ РЕЗУЛЬТАТИ'),t('See what is becoming second nature.','Стежте за стійкістю знань.'),t('Measured accuracy excludes flashcard self-assessment and aided answers. History keeps every answer.','Виміряна точність не враховує самооцінку та відповіді з підказкою. В історії зберігаються всі відповіді.'))+`<div class="stats-grid">${stat(t('Overall progress','Загальний прогрес'),Math.round(s.progress*100)+'<small>%</small>',`${s.learned} / ${s.total} ${t('mastered','засвоєно')}`,'book')}${stat(t('Accuracy','Точність'),s.answers?Math.round(s.accuracy*100)+'<small>%</small>':'—',`${s.answers} ${t('answers','відповідей')}`,'target')}${stat(t('Reaction time','Час реакції'),time(s.averageMs),t('Measured during practice','За результатами практики'),'clock')}${stat(t('Listening accuracy','Точність аудіювання'),audio.length?Math.round(audio.filter(a=>a.correct).length/audio.length*100)+'<small>%</small>':'—',`${audio.length} ${t('audio answers, excluding fallback','аудіовідповідей, без текстового режиму')}`,'headphones')}</div><div class="settings-grid"><section class="panel"><div class="panel-header"><h2>${t('Accuracy over time','Динаміка точності')}</h2><span class="tag">${t('LAST 12 SESSIONS','12 ОСТАННІХ ЗАНЯТЬ')}</span></div>${recent.length?`<div class="chart" role="img" aria-label="${t('Session accuracy chart. Each bar opens the report.','Графік точності. Кожен стовпець відкриває звіт.')}">${recent.map(session=>{const acc=Math.round(session.answers.filter(a=>a.correct).length/Math.max(1,session.answers.length)*100);return `<a href="#/results/${session.id}" style="height:${Math.max(3,acc)}%" aria-label="${e(modeName(session.mode))}: ${acc}%"><span>${acc}%</span></a>`;}).join('')}</div><div class="chart-axis"><span>${date(recent[0].startedAt)}</span><span>${date(recent.at(-1)!.startedAt)}</span></div>`:empty(t('Your learning curve starts here','Початок вашої кривої навчання'),t('Complete your first session to create a real chart.','Пройдіть заняття, щоб побудувати графік.'))}</section><section class="panel"><div class="panel-header"><h2>Communication Readiness</h2><a href="${import.meta.env.BASE_URL}docs/metrics.md" target="_blank" rel="noopener">${t('Formula','Формула')} ↗</a></div>${dict.data.maps.map(m=>`<div class="report-row"><span>${e(m.name)}</span><span class="${m.available?'accent':'muted'}">${m.available?CommunicationReadinessCalculator.calculate(data,dict.positions(m.id).map(p=>p.id))+'%':t('No verified pack','Немає набору')}</span>${m.available?`<div class="progress-track"><span style="width:${CommunicationReadinessCalculator.calculate(data,dict.positions(m.id).map(p=>p.id))}%"></span></div>`:''}</div>`).join('')}<p class="map-note">${t('Learning estimate, not a guarantee of real communication or match success.','Навчальна оцінка, не гарантія успішної гри та комунікації.')}</p></section><section class="panel"><div class="panel-header"><h2>${t('Positions to revisit','Позиції для повторення')}</h2><button data-start="mistakes" class="subtle-button">${t('Review','Повторити')} ↗</button></div>${hard.length?`<ul class="history-list">${hard.map(p=>`<li><button class="subtle-button" data-open-position="${p.id}">${e(dict.name(p.id,data.settings.target))}</button><div>${data.progress[p.id].errors} ${t('misses','помилок')}<small>${t('Next review','Повторення')}: ${date(data.progress[p.id].nextReview)}</small></div></li>`).join('')}</ul>`:empty(t('No weak spots recorded','Помилок поки немає'),t('Mistakes become your next learning opportunity.','Помилки допоможуть визначити подальше навчання.'))}</section><section class="panel"><h2>${t('Round performance','Результати раундів')}</h2><div class="stat-value">${s.round.length?Math.round(s.round.filter(a=>a.correct).length/s.round.length*100)+'%':'—'}</div><p>${s.round.length} ${t('round decisions','рішень у раундах')} · ${t('Average reaction','Середня реакція')}: ${s.round.length?time(s.round.reduce((sum,a)=>sum+a.reactionMs,0)/s.round.length):'—'}</p><div class="section-heading"><h3>${t('Alternative callouts','Альтернативні колаути')}</h3></div><p>${s.aliases.length?Math.round(s.aliases.filter(a=>a.correct).length/s.aliases.length*100)+'%':'—'} · ${s.aliases.length} ${t('alias answers','відповідей з альтернативами')}</p></section></div><div class="section-heading"><h2>${t('Milestones, earned naturally','Досягнення за реальні результати')}</h2><span>${t('No streak pressure','Без нав’язливих серій')}</span></div><div class="achievements">${achievements(data,ids()).map(a=>`<article class="achievement ${a.earned?'earned':''}">${icon('award')}<h3>${e(a.name)} ${a.earned?'✓':''}</h3><p>${e(a.description)}</p></article>`).join('')}</div><div class="section-heading"><h2>${t('Training history','Історія занять')}</h2><span>${data.sessions.length} ${t('sessions','занять')}</span></div><section class="panel">${history(100)}</section>`;}
function settings(){const s=data.settings;return heading(t('PROFILE / PREFERENCES','ПРОФІЛЬ / ПАРАМЕТРИ'),t('Your training, your way.','Навчання за вашими правилами.'),t('Settings and progress are saved only on this device.','Налаштування та прогрес зберігаються лише на цьому пристрої.'))+`<form id="settings-form"><div class="settings-grid"><section class="panel form-grid"><h2>${t('Player & learning','Гравець і навчання')}</h2><label class="field">${t('Player name','Ім’я гравця')}<input name="name" value="${e(s.name)}" maxlength="60" required></label><div class="field-row"><label class="field">${t('Native language / Interface','Основна мова / Інтерфейс')}<select name="native">${options([['uk','Українська'],['en','English']],s.native)}</select></label><label class="field">${t('Learning language','Мова навчання')}<select name="target">${options([['en','English'],['uk','Українська']],s.target)}</select></label></div><label class="field">${t('Active map','Поточна карта')}<select name="mapId"><option value="mirage">Mirage</option></select></label><label class="field">${t('Difficulty / Immersion','Складність / Занурення')}<select name="difficulty">${options([['auto',t('Adaptive · Based on results','Адаптивна · За результатами')],['0','Beginner · 20%'],['1','Adaptation · 50%'],['2','Advanced · 80%'],['3','Match Ready · 100%']],s.difficulty)}</select><small>${t('The percentage changes the actual language mix in new sessions. Current sessions keep their original settings.','Відсоток змінює мову завдань у нових заняттях. Розпочаті заняття зберігають початкові параметри.')}</small></label><label class="field">${t('Self-assessed starting level','Початковий рівень самооцінки')}<select name="initial">${options([['beginner','Beginner'],['intermediate','Intermediate'],['advanced','Advanced']],s.initial)}</select><small>${t('Used provisionally until ten measured answers are available.','Використовується попередньо до десяти виміряних відповідей.')}</small></label><button type="button" data-start="placement">${t('Take placement test','Пройти вступний тест')}</button></section><section class="panel form-grid"><h2>${t('Playback & listening','Відтворення й аудіювання')}</h2><label class="field">${t('Voice source','Тип озвучування')}<select name="audioMode">${options([['recorded',t('Ryan recordings · system fallback','Записи Ryan · системний резерв')],['system',t('System voice only','Лише системний голос')],['off',t('Voice disabled','Озвучування вимкнено')]],s.audioMode)}</select></label><label class="field">${t('Recording playback speed','Швидкість відтворення записів')}<select name="recordedRate">${options([['0.75','0.75×'],['1',t('1× · final processed Ryan voice','1× · фінальний оброблений голос Ryan')],['1.25','1.25×'],['1.5','1.5×']],s.recordedRate)}</select><small>${t('Ryan is already processed to 95% pitch and about 120% speed. 1× applies no further change.','Ryan уже оброблено: висота 95%, швидкість близько 120%. На 1× повторної зміни немає.')}</small></label><label class="field">${t('System voice speed','Швидкість системного голосу')}<input name="rate" type="range" min="0.5" max="1.5" step="0.05" value="${s.rate}"><small>${t('0.5× to 1.5× for system TTS only. This does not change Ryan recordings.','Від 0,5× до 1,5× лише для системного TTS. Це не змінює записи Ryan.')}</small></label><label class="field">${t('Volume','Гучність')}<input name="volume" type="range" min="0" max="1" step="0.05" value="${s.volume}"></label><label class="field">${t('Audio language','Мова аудіо')}<select name="audioLanguage">${options([['adaptive',t('Adaptive language mix','Адаптивне змішування')],['en','English'],['uk','Українська']],s.audioLanguage)}</select><small>${t('An explicit audio language overrides immersion for audio exercises.','Вибрана мова замінює адаптивне змішування в аудіовправах.')}</small></label><label class="checkbox"><input name="subtitles" type="checkbox" ${s.subtitles?'checked':''}>${t('Show subtitles by default','Показувати субтитри за замовчуванням')}</label><button type="button" data-action="test-voice">${icon('volume')} ${t('Test target-language voice','Перевірити голос мови навчання')}</button><div id="voice-diagnostics" class="voice-diagnostics"></div><p class="notice">${t('When present, English recordings use Ryan. Missing clips use an installed local voice; otherwise text fallback appears. Reverse Voice checks typed names, not pronunciation.','За наявності англійські записи використовують Ryan. Для відсутніх записів — установлений локальний голос; інакше текстовий режим. Зворотна голосова вправа перевіряє назву текстом, а не вимову.')}</p></section></div><div class="row" style="margin:22px 0"><button type="submit" class="primary">${t('Save preferences','Зберегти налаштування')}</button><span class="muted" style="font-size:11px">${e(repository.adapter.kind)} · ${t('No cloud sync','Без хмарної синхронізації')}</span></div></form><section class="panel"><h2>${t('Your local data','Ваші локальні дані')}</h2><p style="margin:12px 0 20px">${t('Export a backup before moving devices. Imports are validated before replacing data. A dictionary update preserves stable position IDs and personal progress.','Експортуйте резервну копію для перенесення. Імпорт перевіряється до заміни даних. Оновлення словника зберігає стабільні ідентифікатори та прогрес.')}</p><div class="row wrap"><button data-action="export">${icon('download')} ${t('Export progress JSON','Експорт прогресу JSON')}</button><button data-action="choose-progress-import">${t('Import backup','Імпорт копії')}</button><input class="hide" id="import-progress" type="file" accept="application/json,.json"><button data-action="export-dictionary">${t('Export dictionary','Експорт словника')}</button><button data-action="choose-dictionary-import">${t('Update dictionary','Оновити словник')}</button><input class="hide" id="import-dictionary" type="file" accept="application/json,.json"></div><div class="danger-zone"><button class="danger-button" data-action="delete-progress">${t('Delete personal progress','Видалити особистий прогрес')}</button><p class="map-note">${t('Requires confirmation on this device. This cannot be undone without a backup.','Потрібне підтвердження. Відновлення можливе лише з резервної копії.')}</p></div><div class="source-list">${t('Vocabulary sources, checked 15 November 2026','Джерела лексики, перевірено 15 листопада 2026')}${dict.data.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`).join('')}</div><p id="offline-status" class="map-note"></p></section>`;}
function activeQuestion(s:TrainingSession){return feedback?.q??s.questions[s.index];}
function sessionPage(){const s=currentSession();if(!s){return heading('TRAINING',t('No active session','Немає активного заняття'),t('Choose a training mode to begin.','Виберіть режим для початку.'))+link(t('Open practice','Перейти до практики'),'/practice',true);}const q=activeQuestion(s);if(!q)return '';const sequenceIndex=s.answers.filter(a=>a.questionId===q.id).length;const isFlash=s.mode==='flashcards',isReverse=q.input;const hideText=q.audio&&!transcript&&!data.settings.subtitles&&!audioFallback&&!feedback;
 return `<div class="session-layout">${heading(`MIRAGE / ${modeName(s.mode).toUpperCase()}`,s.mode==='round'?e(scenarios.find(x=>x.id===s.scenarioId)?.name??'Round'):modeName(s.mode),`${levelName(s.level)} · ${LanguageImmersionEngine.ratios[s.level]*100}% ${languageLabel(data.settings.target)} · ${languageLabel(q.language)} ${q.audio?' / AUDIO':''}`,link(t('Save & leave','Зберегти й вийти'),'/'))}<div class="session-top"><div class="row spread" style="margin-bottom:10px"><span class="eyebrow">${t('QUESTION','ЗАПИТАННЯ')} ${Math.min(s.questions.length,feedback?s.index:s.index+1)} / ${s.questions.length}${q.sequence?` · ${t('Selection','Вибір')} ${Math.min(3,sequenceIndex+1)} / 3`:''}</span><span class="timer" id="timer">${q.limitMs?(q.limitMs/1000).toFixed(1)+'s':t('No time limit','Без обмеження часу')}</span></div><div class="progress-track"><span style="width:${s.index/s.questions.length*100}%"></span></div></div>${!running&&!feedback?`<section class="panel paused-cover">${icon('play')}<h2>${t('Your place is saved.','Ваше місце збережено.')}</h2><p>${t('Start when you are ready. The timer begins with the prompt; time away is not counted.','Почніть, коли будете готові. Таймер запуститься із завданням; час відсутності не враховується.')}</p><button class="primary" data-action="resume-question">${t('Continue','Продовжити')} ${icon('arrow')}</button></section>`:`<section class="panel question-panel"><span class="eyebrow">${isFlash?t('DISCOVER THE POSITION','ЗНАЙОМСТВО З ПОЗИЦІЄЮ'):q.input?t('NAME THE HIGHLIGHTED POSITION IN','НАЗВІТЬ ВИДІЛЕНУ ПОЗИЦІЮ МОВОЮ')+' '+languageLabel(q.answerLanguage):q.locate?t('SELECT THE POSITION ON THE MAP','ЗНАЙДІТЬ ПОЗИЦІЮ НА КАРТІ'):q.sequence?t('REPEAT THE THREE POSITIONS IN ORDER','УКАЖІТЬ ТРИ ПОЗИЦІЇ ЗА ПОРЯДКОМ'):t('CHOOSE THE MATCHING CALLOUT','ВИБЕРІТЬ ВІДПОВІДНИЙ КОЛАУТ')}</span><button class="audio-button" data-action="replay" aria-label="${t('Play message again','Повторити повідомлення')}">${icon('volume')}</button><span class="audio-status muted" id="audio-status">${audioFallback?t('Text fallback · no local voice','Текстовий режим · локальний голос недоступний'):t('Listen, then answer. Space to replay.','Слухайте та відповідайте. Пробіл — повторити.')}</span>${!isReverse?`<h2 id="question-text" ${hideText?'class="muted"':''}>${hideText?icon('headphones')+' '+t('Listen to the call','Прослухайте колаут'):e(q.sequence?ListeningTrainingEngine.utterances(q,dict).join(' → '):isFlash?dict.name(q.positionId,data.settings.native):q.text)}</h2>`:''}${isFlash?`<div class="target-image map-host" id="question-map"></div>${revealed?`<h2 class="accent">${e(dict.name(q.positionId,data.settings.target))}</h2><p>${dict.aliases(q.positionId,data.settings.target).map(a=>e(a.name)).join(' / ')}</p>`:`<button data-action="reveal" class="primary">${t('Reveal translation','Показати переклад')}</button>`}`:isReverse?`<div class="target-image map-host" id="question-map"></div><form id="answer-form" class="text-input"><input id="typed-answer" name="answer" aria-label="${t('Type the callout','Введіть колаут')}" placeholder="${t('Type the callout…','Введіть назву…')}" autocomplete="off" required maxlength="200" ${feedback?'disabled':''}><button type="submit" class="primary" ${feedback?'disabled':''}>${t('Check','Перевірити')}</button></form><p class="map-note">${t('Text recognition checks the name and verified aliases, not pronunciation.','Перевіряється назва та підтверджені альтернативи, а не вимова.')}</p>`:q.locate||q.sequence?`<div class="map-host" id="question-map"></div>`:`<div class="answer-options">${q.options.map((id,i)=>`<button class="answer-option ${feedback?(id===q.positionId?'correct':id===feedback.answer.selected?'wrong':''):''}" data-answer="${id}" ${feedback?'disabled':''}><small>${i+1}</small>${e(dict.name(id,q.answerLanguage))}</button>`).join('')}</div>`}${!feedback&&((s.level<2)||(s.mode==='round'&&s.roundMode==='training'))&&!isFlash?`<div class="hint">${hint?`${t('Hint','Підказка')}: ${e(dict.name(q.positionId,data.settings.native))} · ${dict.get(q.positionId).zone}`:`<button class="subtle-button" data-action="hint">${t('Show native-language hint','Підказка основною мовою')}</button>`}</div>`:''}${q.audio&&!feedback?`<button class="subtle-button" data-action="transcript">${hideText?t('Show transcript (aided answer)','Показати текст (відповідь із підказкою)'):t('Hide transcript','Приховати текст')}</button>`:''}${feedback?`<div class="feedback ${feedback.answer.correct?'':'wrong'}" role="status"><div><strong>${feedback.answer.correct?t('Correct. Keep the call flowing.','Правильно. Продовжуйте.'):feedback.answer.timedOut?t('Time is up. Review this position.','Час вичерпано. Повторіть позицію.'):t('Not quite. This one goes to review.','Неправильно. Позицію додано до повторення.')}</strong><p>${e(dict.name(feedback.answer.positionId,'en'))} ↔ ${e(dict.name(feedback.answer.positionId,'uk'))} · ${time(feedback.answer.reactionMs)}${feedback.answer.aided?' · '+t('Aided answer','Із підказкою'):''}</p></div><button class="primary" data-action="next-question">${s.status==='complete'?t('View results','Результати'):t('Next','Далі')} ${icon('arrow')}</button></div>`:''}</section>${isFlash&&revealed&&!feedback?`<div class="session-footer"><button data-answer="__forgot">${t('Still learning','Ще вчу')}</button><p>${t('Self-assessment; excluded from measured accuracy.','Самооцінка; не входить до виміряної точності.')}</p><button class="primary" data-answer="${q.positionId}">${t('Remembered','Пригадав')} ✓</button></div>`:''}<div class="session-footer"><span class="muted">${q.audio?t('Space: replay · 1–4: answer when available','Пробіл: повтор · 1–4: варіант відповіді'):t('1–4: answer · Every answer is saved immediately','1–4: варіант · Кожна відповідь зберігається одразу')}</span><span class="tag">${t('LOCAL SESSION','ЛОКАЛЬНЕ ЗАНЯТТЯ')}</span></div>`}</div>`;
}
function resultsPage(id:string){const s=data.sessions.find(s=>s.id===id);if(!s)return empty(t('Report not found','Звіт не знайдено'),t('The session may have been deleted.','Можливо, заняття було видалено.'))+link(t('Dashboard','Головна'),'/');const correct=s.answers.filter(a=>a.correct).length;const rate=s.answers.length?correct/s.answers.length:0;const errors=s.answers.filter(a=>!a.correct);const avg=s.answers.reduce((sum,a)=>sum+a.reactionMs,0)/Math.max(1,s.answers.length);return heading(`MIRAGE / ${modeName(s.mode).toUpperCase()}`,t('One session closer.','Ще одне заняття позаду.'),t('Your decisions are saved. Review the difficult calls and build from here.','Рішення збережено. Повторюйте складні колаути та продовжуйте навчання.'))+`<div class="panel summary-score"><span class="eyebrow">${s.mode==='flashcards'?t('SELF-ASSESSMENT','САМООЦІНКА'):t('SESSION ACCURACY','ТОЧНІСТЬ ЗАНЯТТЯ')}</span><strong>${Math.round(rate*100)}%</strong><h2>${correct} / ${s.answers.length} ${t('correct answers','правильних відповідей')}</h2><p style="margin:12px auto 0">${t('Average reaction','Середня реакція')}: ${time(avg)} · ${errors.length} ${t('positions to revisit','помилок для повторення')}</p><div class="row wrap" style="justify-content:center;margin-top:25px"><button class="primary" data-retry="${s.id}">${t(s.mode==='round'?'Retry Round':'Try again',s.mode==='round'?'Повторити раунд':'Повторити заняття')}</button>${s.mode==='round'?`<button data-action="next-scenario">${t('Next Scenario','Наступний сценарій')}</button>`:''}${errors.length?`<button data-start="mistakes">${t('Review Mistakes','Повторити помилки')}</button>`:''}${link(t('Back to Dashboard','На головну'),'/')}</div></div>${s.mode==='placement'?`<div class="notice" style="margin-top:20px">${t('Suggested starting level','Рекомендований початковий рівень')}: ${rate>=.9?'Advanced':rate>=.6?'Intermediate':'Beginner'}. <button data-placement="${rate>=.9?'advanced':rate>=.6?'intermediate':'beginner'}">${t('Apply recommendation','Застосувати рекомендацію')}</button></div>`:''}<div class="section-heading"><h2>${t('Decision breakdown','Розбір відповідей')}</h2><span>${date(s.startedAt)}</span></div><section class="panel"><div class="table-scroll"><table class="results-table"><thead><tr><th>${t('Position','Позиція')}</th><th>${t('Your answer','Ваша відповідь')}</th><th>${t('Result','Результат')}</th><th>${t('Reaction','Реакція')}</th></tr></thead><tbody>${s.answers.map(a=>`<tr><td>${e(dict.name(a.positionId,data.settings.target))}<br><small class="muted">${e(dict.name(a.positionId,data.settings.native))}</small></td><td>${e(a.selected.startsWith('mirage.')?dict.name(a.selected,data.settings.target):a.selected==='__timeout'?t('No answer','Немає відповіді'):a.selected==='__forgot'?t('Still learning','Ще вчу'):a.selected)}</td><td class="${a.correct?'accent':'danger'}">${a.correct?'✓':'×'} ${a.timedOut?t('Timed out','Час вичерпано'):a.correct?t('Correct','Правильно'):t('Review','Повторити')}${a.aided?`<br><small>${t('Aided','Із підказкою')}</small>`:''}</td><td>${time(a.reactionMs)}</td></tr>`).join('')}</tbody></table></div><p class="map-note">${errors.length?t('Recommendation: review the missed positions before trying a faster round.','Рекомендація: повторіть помилки перед прискореним раундом.'):t('Recommendation: return after the scheduled interval to test retention, or try a different exercise type.','Рекомендація: поверніться в призначений термін для перевірки пам’яті або виберіть інший тип вправи.')}</p></section>`;}
let feedbackSessionId:string|null=null;
function render(){
 unmountMaps();
 clearInterval(timer);timer=undefined;
 if(!data.settings.onboarding){root.innerHTML=onboarding();bind();return;}
 document.documentElement.lang=data.settings.native;
 const path=route();let content='';
 if(path==='/')content=dashboard();else if(path==='/maps')content=mapsPage();else if(path==='/learn')content=mapsPage(true);else if(path==='/practice')content=practice();else if(path==='/listening')content=listening();else if(path==='/voice')content=listening(true);else if(path==='/round')content=roundPage();else if(path==='/stats')content=statistics();else if(path==='/settings')content=settings();else if(path==='/session')content=sessionPage();else if(path.startsWith('/results/'))content=resultsPage(path.slice(9));else content=empty(t('Unknown route','Невідомий розділ'),t('Choose a section in the navigation.','Виберіть розділ у навігації.'))+link(t('Dashboard','Головна'),'/');
 root.innerHTML=shell(content);document.title=`Callout · ${titleForRoute()}`;
 bind();
 if(path==='/'){const host=document.querySelector<HTMLElement>('#dashboard-map');if(host)mountMap(host,{dictionary:dict,interfaceLanguage:data.settings.native,language:'en',ids:['mirage.a-site','mirage.b-site','mirage.window','mirage.palace','mirage.connector','mirage.jungle','mirage.mid','mirage.short','mirage.apartments','mirage.ramp'],compact:true,onSelect:id=>{selected=id;go('/maps');}});}
 if(path==='/maps'||path==='/learn')updateExplorer();
 if(path==='/session'){
  const s=currentSession();const q=s?activeQuestion(s):null;if(s)void preloadSession(s);const host=document.querySelector<HTMLElement>('#question-map');
  if(host&&s&&q)mountMap(host,{dictionary:dict,interfaceLanguage:data.settings.native,language:'en',hidden:true,selected:s.mode==='flashcards'||q.input?q.positionId:feedback?.answer.positionId,compact:s.mode==='flashcards'||q.input,onSelect:id=>{if(!q.input&&s.mode!=='flashcards'&&!feedback&&running)void safe(()=>submit(id));}});
  if(running&&!feedback&&q){beginTimer(q);document.querySelector<HTMLInputElement>('#typed-answer')?.focus();}
 }
 if(path==='/settings'){void updateOfflineStatus();updateVoiceDiagnostics();}
}
function updateExplorer(){const host=document.querySelector<HTMLElement>('#explorer-map');const card=document.querySelector<HTMLElement>('#position-card');if(!host||!card)return;const positions=dict.search(search,zone);const count=document.querySelector('#map-count');if(count)count.textContent=`${positions.length} / ${dict.positions().length} ${t('positions','позицій')}`;mountMap(host,{dictionary:dict,interfaceLanguage:data.settings.native,language:mapLanguage,hidden:mapHidden,selected,ids:positions.map(p=>p.id),onSelect:id=>{selected=id;card.innerHTML=positionCard();}});card.innerHTML=positionCard();}
function preloadSession(s:TrainingSession){if(data.settings.audioMode!=='recorded')return Promise.resolve([]);return Promise.all(s.questions.slice(s.index,s.index+4).map(q=>{const prompt=exerciseAudio(q,s.mode,dict,data.settings);return voice.preload(prompt.requests,prompt.language);}));}
function startClock(){const s=currentSession();clock.start(s?.questions[s.index]?.limitMs??0,performance.now());}
function beginTimer(q:Question){if(!q.limitMs)return;const update=()=>{const remaining=clock.remaining(performance.now());const el=document.querySelector('#timer');if(el)el.textContent=(remaining/1000).toFixed(1)+'s';if(remaining===0&&running&&!feedback&&!saving){clearInterval(timer);void safe(()=>submit('__timeout',true));}};update();timer=setInterval(update,100);}
async function playQuestion(resetTimer=false,manual=false){const s=currentSession();if(!s)return;const q=activeQuestion(s);if(!q||(!q.audio&&!manual)||(q.input&&!manual))return;const prompt=exerciseAudio(q,s.mode,dict,data.settings);if(manual&&prompt.revealsAnswer)hint=true;if(manual&&s.mode==='flashcards'&&!revealed){revealed=true;render();}const token=++voicePlayToken;playing=true;initialPlayback=resetTimer;if(resetTimer)clock.pause(performance.now());const status=document.querySelector('#audio-status');if(status)status.textContent=t('Playing audio…','Відтворення озвучування…');const rate=s.mode==='voice'||s.mode==='round'?Math.min(1.5,data.settings.rate+s.index*.035):data.settings.rate;
 const success=await voice.play(prompt.requests,prompt.language,{...data.settings,rate});if(token!==voicePlayToken)return;playing=false;initialPlayback=false;if(route()!=='/session'||!running||feedback)return;
 if(resetTimer)startClock();audioHeard=audioHeard||success;audioFallback=audioFallback||!success;
 if(!success){const text=document.querySelector('#question-text');if(text){text.textContent=q.sequence?ListeningTrainingEngine.utterances(q,dict).join(' → '):q.text;text.classList.remove('muted');}}
 const message=document.querySelector('#audio-status');if(message)message.textContent=success?(voice.lastSource==='recorded'?t('Ryan recording · Space to replay','Запис Ryan · Пробіл: повторити'):t('System voice · Space to replay','Системний голос · Пробіл: повторити')):voiceFailureMessage()+' · '+t('Text fallback; no audio credit.','Текстовий режим; без аудіобалів.');
}
async function startSession(mode:Mode,scenarioIndex=0){stop();feedback=null;feedbackSessionId=null;const next=structuredClone(data);const s=engine.start(next,mode,scenarioIndex);if(next.activeSessionId){const old=next.sessions.find(x=>x.id===next.activeSessionId);if(old?.answers.length===0)next.sessions=next.sessions.filter(x=>x.id!==old.id);}
 next.sessions.push(s);next.activeSessionId=s.id;await commit(next);revealed=false;hint=false;transcript=false;audioFallback=false;audioHeard=false;running=true;startClock();if(route()!=='/session'){location.hash='/session';}else render();
 // Play after hash-route rendering. Restrictive browsers may require the explicit speaker button.
 setTimeout(()=>{if(route()==='/session'&&running)void playQuestion(true);},30);
}
async function submit(selectedAnswer:string,timedOut=false){if(saving||feedback||!running)return;const s=currentSession();if(!s)return;const q=s.questions[s.index];if(!q)return;if(playing&&initialPlayback){toast(t('Wait for the message to finish.','Дочекайтеся завершення повідомлення.'));return;}clearInterval(timer);const elapsed=clock.elapsed(performance.now());const answer=engine.answer(s,selectedAnswer,Math.min(86400000,elapsed),Date.now(),timedOut);answer.aided=hint||transcript||(q.audio&&data.settings.subtitles);answer.audio=q.audio&&audioHeard&&!audioFallback&&!answer.aided;
 const next=ProgressTrackingService.record(data,s.id,answer);await commit(next);voice.cancel();playing=false;feedback={answer,q};feedbackSessionId=s.id;render();document.querySelector<HTMLButtonElement>('[data-action="next-question"]')?.focus();
}
function nextQuestion(){const s=currentSession();if(!s)return;if(s.status==='complete'){const id=s.id;stop();feedback=null;feedbackSessionId=null;go('/results/'+id);return;}feedback=null;revealed=false;hint=false;transcript=false;audioFallback=false;audioHeard=false;startClock();running=true;render();void playQuestion(true);}
function settingsFromForm(form:HTMLFormElement):UserSettings{const values=new FormData(form);const s={...data.settings};s.name=String(values.get('name')??s.name).trim()||'Player';s.native=values.get('native') as UserSettings['native'];s.target=values.get('target') as UserSettings['target'];s.initial=values.get('initial') as UserSettings['initial'];s.mapId=String(values.get('mapId')??s.mapId);if(s.native===s.target)throw new Error(t('Choose two different languages.','Виберіть дві різні мови.'));if(values.has('difficulty'))s.difficulty=values.get('difficulty')==='auto'?'auto':Number(values.get('difficulty')) as UserSettings['difficulty'];if(values.has('audioMode')){s.audioMode=values.get('audioMode') as UserSettings['audioMode'];s.recordedRate=Number(values.get('recordedRate'));}if(values.has('rate')){s.rate=Number(values.get('rate'));s.volume=Number(values.get('volume'));s.subtitles=values.get('subtitles')==='on';s.audioLanguage=values.get('audioLanguage') as UserSettings['audioLanguage'];}return s;}
async function safe(action:()=>Promise<void>|void){try{await action();}catch(error){if(route()==='/session'){stop();render();}toast(error instanceof Error?error.message:String(error),true);}}
function bind(){
 root.querySelectorAll<HTMLFormElement>('#onboarding-form,#settings-form').forEach(form=>form.onsubmit=ev=>{ev.preventDefault();void safe(async()=>{const next=structuredClone(data);next.settings=settingsFromForm(form);next.settings.onboarding=true;const placement=new FormData(form).has('placement');await commit(next);stop();render();toast(t('Preferences saved on this device.','Налаштування збережено на пристрої.'));if(placement)await startSession('placement');});});
 root.querySelector<HTMLFormElement>('#answer-form')?.addEventListener('submit',ev=>{ev.preventDefault();const answer=document.querySelector<HTMLInputElement>('#typed-answer')?.value.trim();if(answer)void safe(()=>submit(answer));});
 const native=root.querySelector<HTMLSelectElement>('select[name=native]'),target=root.querySelector<HTMLSelectElement>('select[name=target]');if(native&&target){native.onchange=()=>{target.value=native.value==='uk'?'en':'uk';};target.onchange=()=>{native.value=target.value==='uk'?'en':'uk';};}
 root.querySelector<HTMLInputElement>('#position-search')?.addEventListener('input',ev=>{search=(ev.target as HTMLInputElement).value;updateExplorer();});
 root.querySelector<HTMLSelectElement>('#zone')?.addEventListener('change',ev=>{zone=(ev.target as HTMLSelectElement).value;updateExplorer();});
 root.querySelector<HTMLSelectElement>('#map-language')?.addEventListener('change',ev=>{mapLanguage=(ev.target as HTMLSelectElement).value as typeof mapLanguage;updateExplorer();});
 root.querySelector<HTMLInputElement>('#hide-labels')?.addEventListener('change',ev=>{mapHidden=(ev.target as HTMLInputElement).checked;updateExplorer();});
 root.querySelector<HTMLSelectElement>('#round-mode')?.addEventListener('change',ev=>{void safe(async()=>{const next=structuredClone(data);next.settings.roundMode=(ev.target as HTMLSelectElement).value as UserSettings['roundMode'];await commit(next);});});
 root.querySelector<HTMLInputElement>('#import-progress')?.addEventListener('change',ev=>{void safe(async()=>{const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5_000_000)throw new Error('Maximum import size is 5 MB');const text=await file.text();const next=validateData(migrateData(JSON.parse(text)),dictionary);if(!confirm(t('Replace local progress with this validated backup? Export first if needed.','Замінити локальний прогрес перевіреною копією? За потреби спочатку експортуйте дані.')))return;stop();await commit(next);feedback=null;render();toast(t('Backup imported.','Копію імпортовано.'));});});
 root.querySelector<HTMLInputElement>('#import-dictionary')?.addEventListener('change',ev=>{void safe(async()=>{const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5_000_000)throw new Error('Maximum import size is 5 MB');const nextDictionary=validateDictionary(JSON.parse(await file.text()));const referenced=new Set([...Object.keys(data.progress),...data.review,...data.sessions.flatMap(s=>s.questions.flatMap(q=>[q.positionId,...q.options,...(q.sequence??[])]))]);if([...referenced].some(id=>!nextDictionary.positions.some(p=>p.id===id)))throw new Error(t('Update removes a position used by your history. Keep stable IDs.','Оновлення видаляє позицію з історії. Збережіть стабільні ID.'));if(nextDictionary.version<(data.dictionary??dictionary).version)throw new Error(t('Dictionary version must not go backwards.','Версія словника не має зменшуватися.'));const next=structuredClone(data);next.dictionary=nextDictionary;await commit(next);render();toast(t('Dictionary updated; progress preserved.','Словник оновлено; прогрес збережено.'));});});
}
root.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest<HTMLElement>('[data-action],[data-start],[data-answer],[data-select],[data-open-position],[data-scenario],[data-retry],[data-placement],[data-resume-session]');if(!el||saving)return;void safe(async()=>{
 if(el.dataset.resumeSession){const next=structuredClone(data);next.activeSessionId=el.dataset.resumeSession;await commit(next);stop();feedback=null;feedbackSessionId=null;go('/session');return;}
 if(el.dataset.start){await startSession(el.dataset.start as Mode);return;}
 if(el.dataset.answer){await submit(el.dataset.answer);return;}
 if(el.dataset.select){selected=el.dataset.select;updateExplorer();return;}
 if(el.dataset.openPosition){selected=el.dataset.openPosition;search='';zone='all';go('/maps');return;}
 if(el.dataset.scenario!==undefined){await startSession('round',Number(el.dataset.scenario));return;}
 if(el.dataset.retry){const s=data.sessions.find(s=>s.id===el.dataset.retry)!;const scenarioIndex=Math.max(0,scenarios.findIndex(x=>x.id===s.scenarioId));await startSession(s.mode,scenarioIndex);return;}
 if(el.dataset.placement){const next=structuredClone(data);next.settings.initial=el.dataset.placement as UserSettings['initial'];await commit(next);toast(t('Starting level updated.','Початковий рівень оновлено.'));return;}
 switch(el.dataset.action){
 case 'resume-question':audioHeard=false;audioFallback=false;running=true;revealed=false;hint=false;transcript=false;startClock();render();await playQuestion(true);break;
 case 'next-question':nextQuestion();break;
 case 'reveal':revealed=true;render();break;
 case 'hint':hint=true;render();break;
 case 'transcript':transcript=!transcript;render();break;
 case 'replay':await playQuestion(false,true);break;
 case 'speak-position':{const ok=await voice.speak([dict.name(selected,data.settings.target)],data.settings.target,data.settings,[selected]);if(!ok)toast(voiceFailureMessage());break;}
 case 'save-review':{const next=structuredClone(data);next.review=next.review.includes(selected)?next.review.filter(id=>id!==selected):[...next.review,selected];await commit(next);updateExplorer();toast(t('Review list updated.','Список повторення оновлено.'));break;}
 case 'select-mirage':{const next=structuredClone(data);next.settings.mapId='mirage';await commit(next);toast(t('Mirage is your active map.','Mirage — поточна карта.'));break;}
 case 'test-voice':{const form=root.querySelector<HTMLFormElement>('#settings-form')!;const prefs=settingsFromForm(form);const ok=await voice.speak([dict.name('mirage.window',prefs.target)],prefs.target,prefs,['mirage.window']);updateVoiceDiagnostics();if(!ok)toast(voiceFailureMessage());break;}
 case 'next-scenario':{const last=[...data.sessions].reverse().find(s=>s.mode==='round');const index=last?scenarios.findIndex(x=>x.id===last.scenarioId)+1:0;await startSession('round',index);break;}
 case 'choose-progress-import':root.querySelector<HTMLInputElement>('#import-progress')?.click();break;
 case 'choose-dictionary-import':root.querySelector<HTMLInputElement>('#import-dictionary')?.click();break;
 case 'export':download('callout-progress.json',data);break;
 case 'export-dictionary':download('callout-dictionary.json',dict.data);break;
 case 'delete-progress':{if(!confirm(t('Delete all personal training answers, sessions and progress? Export first to keep a backup.','Видалити всі відповіді, заняття та прогрес? Спочатку експортуйте дані, якщо потрібна копія.')))break;stop();const next=emptyData();next.settings={...data.settings};next.dictionary=data.dictionary;await commit(next);feedback=null;feedbackSessionId=null;render();toast(t('Personal progress deleted.','Особистий прогрес видалено.'));break;}
 }
});});
function download(name:string,value:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
window.addEventListener('hashchange',()=>{if(route()!=='/session'){stop();feedback=null;feedbackSessionId=null;}render();window.scrollTo(0,0);});
document.addEventListener('keydown',ev=>{if(route()!=='/session'||!running||feedback||['INPUT','SELECT','TEXTAREA'].includes((ev.target as HTMLElement).tagName))return;if(['1','2','3','4'].includes(ev.key)){const buttons=root.querySelectorAll<HTMLButtonElement>('[data-answer]');buttons[Number(ev.key)-1]?.click();}else if(ev.code==='Space'&&currentSession()?.questions[currentSession()!.index]){ev.preventDefault();void playQuestion(false,true);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&route()==='/session'&&running&&!feedback){stop();render();}});
async function updateOfflineStatus(){const el=document.querySelector('#offline-status');if(!el)return;const reg='serviceWorker' in navigator?await navigator.serviceWorker.getRegistration():null;el.textContent=reg?.active?t('Offline app cache installed. Ryan recordings are cached too; Ukrainian system fallback still needs an installed voice.','Офлайн-кеш застосунку встановлено. Записи Ryan також кешуються; для українського системного голосу потрібен установлений голосовий пакет.'):t('Offline cache is installed by the production build on HTTPS or localhost. Development server is not cached.','Офлайн-кеш встановлюється production-збіркою на HTTPS або localhost. Dev-сервер не кешується.');}

function voiceFailureMessage(){
 if(voice.lastError==='not-allowed')return t('Browser blocked playback. Press the speaker again and check this site’s sound permission.','Браузер заблокував відтворення. Натисніть динамік ще раз і перевірте дозвіл звуку для сайту.');
 if(voice.lastError==='disabled')return t('Voice is disabled in Settings.','Озвучування вимкнене в налаштуваннях.');
 if(voice.lastError==='muted')return t('Volume is zero. Increase it in Settings.','Гучність дорівнює нулю. Збільште її в налаштуваннях.');
 if(voice.lastError==='unsupported')return t('This browser does not provide speech synthesis. Try a browser with Web Speech support.','Цей браузер не надає синтезу мовлення. Скористайтеся браузером із підтримкою Web Speech.');
 if(voice.lastError==='no-local-voice')return t('No installed local voice for this language. Check the voice list in Settings.','Для цієї мови немає встановленого локального голосу. Перевірте список голосів у налаштуваннях.');
 return t('Playback failed. Check the sound output device, volume and speech service.','Помилка відтворення. Перевірте пристрій виведення звуку, гучність і службу синтезу мовлення.');
}
function updateVoiceDiagnostics(){const el=document.querySelector('#voice-diagnostics');if(!el)return;el.innerHTML=(['en','uk'] as const).map(lang=>{const voices=voice.voices().filter(v=>v.localService&&v.lang.toLowerCase().replace('_','-').split('-')[0]===lang);return `<div><strong>${languageLabel(lang)}</strong>: ${voice.recordedCount(lang)} ${t('recordings','записів')} · ${voices.length?voices.map(v=>e(v.name)).join(', '):t('no installed local voice','немає встановленого локального голосу')}</div>`;}).join('')+`<div>${t('If playback is blocked, press the speaker button to enable sound.','Якщо відтворення заблоковано, натисніть кнопку динаміка, щоб увімкнути звук.')}</div>`;}

async function boot(){try{validateDictionary(dictionary);repository=new LocalRepository(await createStorage(),dictionary);data=await repository.load();dict=new PositionDictionaryService(data.dictionary??dictionary);engine=new LearningEngine(dict);render();void voice.prepare().then(()=>{if(['/listening','/voice'].includes(route()))render();else updateVoiceDiagnostics();});if(import.meta.env.PROD&&'serviceWorker' in navigator){navigator.serviceWorker.register(import.meta.env.BASE_URL+'sw.js').catch(()=>toast(t('Offline cache unavailable; local progress still works.','Офлайн-кеш недоступний; локальний прогрес продовжує працювати.')));}}catch(error){root.innerHTML=`<main class="boot"><h1>Callout</h1><div class="notice error">${e(error instanceof Error?error.message:error)}</div><p style="margin:20px auto">Local data could not be loaded. Existing data has not been overwritten.<br>Не вдалося завантажити дані. Збережений прогрес не перезаписано.</p><button id="retry-load">Retry / Повторити</button> <button id="rescue-export">Export raw data / Експорт даних</button></main>`;document.querySelector('#retry-load')?.addEventListener('click',()=>location.reload());document.querySelector('#rescue-export')?.addEventListener('click',()=>{void safe(async()=>{if(repository)download('callout-recovery.json',await repository.adapter.load());else throw new Error('Device storage is unavailable. Check browser storage permissions.');});});}}
void boot();
